(function(){
'use strict';
// Standalone 60-second demo animation exporter; uses the selected pet's actual uploaded/demo photo.
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
let active=false;
function drawCover(ctx,img,w,h,t){const scale=Math.max(w/img.width,h/img.height)*(1+0.014*Math.sin(t*2*Math.PI/4));const iw=img.width*scale,ih=img.height*scale;const dx=(w-iw)/2+Math.sin(t*.8)*3,dy=(h-ih)/2+Math.sin(t*2*Math.PI/3)*6;ctx.drawImage(img,dx,dy,iw,ih)}
function wave(ctx,y,w,t,breath){ctx.beginPath();for(let i=0;i<w;i+=2){let p=i/(breath?135:82)-t*(breath?.8:1.8),z;if(breath)z=Math.sin(p*Math.PI*2)*.36;else{let q=((p%1)+1)%1;z=q>.43&&q<.51?Math.sin((q-.43)/.08*Math.PI)*.86:q>.51&&q<.58?-.24*Math.sin((q-.51)/.07*Math.PI):Math.sin(q*Math.PI*2)*.045}let yy=y-z*26;i?ctx.lineTo(i,yy):ctx.moveTo(i,yy)}ctx.strokeStyle=breath?'#86d8ff':'#ff9db7';ctx.lineWidth=3;ctx.stroke()}
function text(ctx,s,x,y,size=25,weight='normal'){ctx.font=weight+' '+size+'px system-ui,sans-serif';ctx.fillStyle='#fff';ctx.fillText(s,x,y)}
function recorderType(){if(!window.MediaRecorder)return null;return ['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(x=>MediaRecorder.isTypeSupported(x))||null}
async function exportMovie(){if(active)return;const petCanvas=document.getElementById('dp-petcanvas');if(!petCanvas){alert('请先打开60秒心跳时刻');return}const mime=recorderType();if(!mime||!HTMLCanvasElement.prototype.captureStream){alert('当前浏览器不支持 WebM 影片录制。请使用最新版 Chrome 或 Edge。');return}const img=new Image();img.src=petCanvas.toDataURL('image/png');await img.decode();const score=document.querySelector('.dp-score-ring strong')?.textContent?.trim()||'—',name=document.querySelector('.dp-stage-top span')?.textContent?.trim()||'DeepPet',mood=document.querySelector('.dp-mood-copy strong')?.textContent?.trim()||'',stat=[...document.querySelectorAll('.dp-stage-stats>div')].map(x=>x.innerText.replace(/\s+/g,' ').trim());const c=document.createElement('canvas');c.width=720;c.height=1280;const ctx=c.getContext('2d');const stream=c.captureStream(24);let rec;try{rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:2200000})}catch(e){alert('录制启动失败：'+e.message);return}let parts=[];rec.ondataavailable=e=>{if(e.data.size)parts.push(e.data)};const btn=document.getElementById('dp-record-video');active=true;btn.disabled=true;rec.start(1000);const start=performance.now();function frame(now){if(!active)return;let t=Math.min(60,(now-start)/1000);ctx.clearRect(0,0,720,1280);drawCover(ctx,img,720,1280,t);let shade=ctx.createLinearGradient(0,480,0,1280);shade.addColorStop(0,'#0d102000');shade.addColorStop(1,'#0d1020ef');ctx.fillStyle=shade;ctx.fillRect(0,480,720,800);text(ctx,name,35,60,30,'bold');text(ctx,'00:'+String(Math.floor(t)).padStart(2,'0')+' / 01:00',490,60,24);ctx.fillStyle='#ffffff20';ctx.fillRect(34,730,652,2);text(ctx,mood+' · '+score+'/100',35,807,45,'bold');stat.slice(0,4).forEach((s,i)=>text(ctx,s,35+(i%2)*350,875+Math.floor(i/2)*55,23));text(ctx,'心搏波形 · 模拟',35,1022,20);wave(ctx,1070,650,t,false);text(ctx,'呼吸波形 · 模拟',35,1130,20);wave(ctx,1182,650,t,true);text(ctx,'DeepPet · 模拟数据 · 照片轻微动态效果',35,1250,17);btn.textContent='录制中 '+Math.floor(t)+'/60 秒';if(t<60)requestAnimationFrame(frame);else{active=false;rec.stop()}}requestAnimationFrame(frame);rec.onstop=()=>{stream.getTracks().forEach(x=>x.stop());btn.disabled=false;btn.textContent='🎬 保存60秒动画影片';if(!parts.length){alert('未生成影片数据');return}const url=URL.createObjectURL(new Blob(parts,{type:mime}));const a=document.createElement('a');a.href=url;a.download='DeepPet_HeartMoment_60s.webm';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}}
function mount(){const actions=document.querySelector('.dp-stage-actions');if(!actions||document.getElementById('dp-record-video'))return;const btn=document.createElement('button');btn.id='dp-record-video';btn.type='button';btn.textContent='🎬 保存60秒动画影片';btn.onclick=exportMovie;actions.appendChild(btn);const note=document.createElement('p');note.style.cssText='font-size:11px;color:#fff;opacity:.85;margin:6px 0 0';note.textContent='模拟照片轻微动态、动态波形与60秒录制；非AI生成真实眨眼或嘴部动作。';actions.appendChild(note)}
const observer=new MutationObserver(()=>{if(document.getElementById('dp-petcanvas'))mount()});observer.observe(document.body,{childList:true,subtree:true});
})();